package com.giovannielena.restaurant.service;
import com.giovannielena.restaurant.dto.OrderDtos.AddressRequest; import com.giovannielena.restaurant.entity.*; import com.giovannielena.restaurant.repository.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class AddressService { private final AddressRepository addresses; private final UserRepository users; public AddressService(AddressRepository a,UserRepository u){addresses=a;users=u;} public List<Address> mine(String email){return addresses.findByUserIdOrderByDefaultAddressDesc(users.findByEmail(email).orElseThrow().getId());} public Address add(String email,AddressRequest r){User u=users.findByEmail(email).orElseThrow(); if(r.defaultAddress())addresses.findByUserIdOrderByDefaultAddressDesc(u.getId()).forEach(a->{a.setDefaultAddress(false);addresses.save(a);}); Address a=new Address();a.setUser(u);a.setAddressLine(r.addressLine());a.setCity(r.city());a.setPostalCode(r.postalCode());a.setDefaultAddress(r.defaultAddress());return addresses.save(a);} }